import test from "node:test";
import assert from "node:assert/strict";

// A delayed or failed effect catalog must not prevent the reported lighting controls from becoming usable.
for (const failure of [false, true]) test(`startup hydrates controls before a ${failure ? "failed" : "delayed"} catalog`, { timeout: 4000 }, async () => {
	const original = Object.fromEntries(["document", "window", "location", "fetch", "setTimeout"].map((key) => [key, globalThis[key]]));
	const controls = new Map(), listeners = new Map(), commands = [], timers = [], delays = [];
	let enabled = false, finishCatalog, catalogStarted, scheduled, sentLighting;
	const started = new Promise((resolve) => { catalogStarted = resolve; });
	const polling = new Promise((resolve) => { scheduled = resolve; });
	const catalog = new Promise((resolve) => { finishCatalog = resolve; });
	const lighting = new Promise((resolve) => { sentLighting = resolve; });
	const status = { ok: true, master: true, settled: true, localId: "001122334455", devices: [] };
	globalThis.document = {
		hidden: false, readyState: "complete",
		addEventListener(name, handler) { listeners.set(name, handler); },
		getElementById(id) {
			if (!controls.has(id)) controls.set(id, { hidden: id === "inlineSettings", value: "all" });
			return controls.get(id);
		},
	};
	globalThis.window = { addEventListener() {} };
	globalThis.location = { origin: "http://device", hostname: "device", host: "device" };
	globalThis.setTimeout = (handler, delay, ...args) => {
		delays.push(delay);
		const timer = original.setTimeout(handler, delay, ...args);
		timers.push(timer);
		if (delay === 30000 || delay === 3000) scheduled(delay);
		return timer;
	};
	globalThis.fetch = async (address, options = {}) => {
		if (address === "/json/effects") {
			assert.equal(enabled, true);
			catalogStarted();
			await catalog;
			return failure ? new Response(null, { status: 503 }) : Response.json(["Solid", "Blink"]);
		}
		if (address.endsWith("/request")) return Response.json({ id: "a".repeat(32) });
		if (address.includes("/rpc?")) {
			commands.push(JSON.parse(options.body));
			if (commands.at(-1).op === "lighting") sentLighting();
			return new Response(null, { status: 202 });
		}
		return Response.json(status);
	};
	try {
		await import(`../web/app.js?startup-${failure}`);
		window.glassDeviceBridge.start({
			setEnabled(value) { enabled = value; }, receivePixels() {},
			receiveDevices(value) { assert.deepEqual(value.devices, []); },
			receiveEffects(value) { assert.equal(failure, false); assert.deepEqual(value, ["Solid", "Blink"]); },
		});
		await started;
		assert.equal(enabled, true);
		assert.deepEqual(commands, [{ op: "status" }]);
		window.glassDeviceBridge.change("all", { brightness: 65 }, ["brightness"]);
		await lighting;
		assert.deepEqual(commands[1], { op: "lighting", target: "all", body: { independent: true, bri: 166 } });
		finishCatalog();
		assert.equal(await polling, 30000);
		await new Promise((resolve) => original.setTimeout(resolve, 0));
		if (failure) assert.match(controls.get("feedback").textContent, /Unable to load WLED effects/);
		// Settings uses the shorter polling interval; a hidden tab clears that pending refresh.
		controls.get("inlineSettings").hidden = false;
		listeners.get("visibilitychange")();
		assert.equal(delays.at(-1), 3000);
		document.hidden = true;
		listeners.get("visibilitychange")();
		assert.equal(enabled, true);
	} finally {
		finishCatalog();
		for (const timer of timers) clearTimeout(timer);
		Object.assign(globalThis, original);
	}
});
// AI: end
